import { readFile, writeFile } from "node:fs/promises"
import { Effect } from "effect"

const sourcePath = "var/search/terms.txt"
const dictionaryPath = "var/search/dictionary.json"

const readTerms = Effect.tryPromise(() => readFile(sourcePath, "utf8"))

const normalizeTerms = (source: string): ReadonlyArray<string> =>
  Array.from(
    new Set(
      source
        .split("\n")
        .map((term) => term.trim().toLowerCase())
        .filter((term) => term.length > 0)
    )
  ).sort()

export const rebuildDictionary = Effect.fn("search.rebuildDictionary")(function* () {
  const source = yield* readTerms
  const terms = normalizeTerms(source)

  yield* Effect.tryPromise(() =>
    writeFile(dictionaryPath, JSON.stringify({ terms }), "utf8")
  )

  return terms.length
})

export const publishDictionary = Effect.gen(function* () {
  const count = yield* rebuildDictionary()
  yield* Effect.logInfo(`Published search dictionary with ${count} terms`)
  return { path: dictionaryPath, count }
})

